/* === FIM DOS DADOS GERADOS ================================================= */

(() => {
  'use strict';

  const CONFIG = {
    totalDuration: 2400,     // ms — duração total da escrita (menor = traço mais rápido)
    leadIn: 110,             // ms — instante antes de a caneta encostar
    liftInGroup: 70,         // ms — caneta no ar entre movimentos do mesmo grupo
    liftBetweenGroups: 110,  // ms — caneta no ar entre grupos
    tailHold: 60,            // ms — respiro depois do último traço

    curvWindow: 4,           // amostras usadas para medir a curvatura local
    minRadius: 7,            // px de arte — abaixo disso é considerado "bico"
    maxRadius: 330,          // px de arte — acima disso é considerado "reta"
    speedExponent: 1 / 3,    // lei da potência 2/3
    speedSmooth: 7,          // média móvel do perfil de velocidade

    entryRamp: 60,           // px de arte — aceleração no início do movimento
    exitRamp: 95,            // px de arte — desaceleração no fim do movimento
    rampFloor: 0.32,         // fração da velocidade máxima nas pontas

    // quanto da caixa disponível a assinatura ocupa. 1 = encosta nas bordas;
    // abaixo disso ela respira e sobra espaço pro texto de baixo crescer.
    fillRatio: 0.82
  };

  /* A assinatura é escrita UMA única vez, no carregamento da página. Não há
     replay por tecla nem ao voltar pro topo — depois de pronta ela permanece
     desenhada, e só é redesenhada (já completa) em resize. */

  const DATA = SIGNATURE_DATA;
  const canvas = document.getElementById('assinatura');
  if (!canvas) return;                        // página sem a hero da assinatura

  const stage = canvas.parentElement;
  const ctx = canvas.getContext('2d', { alpha: true });

  // cor do traço: vem do tema do portfólio, com fallback na cor do dado original
  const COLOR = (getComputedStyle(document.documentElement)
                  .getPropertyValue('--lightgreen') || '').trim() || DATA.color;

  // ---------------------------------------------------------------- utilidades
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);

  /* ============================================================================
     1. PREPARO DOS MOVIMENTOS
     Para cada movimento: comprimentos de arco, curvatura, velocidade e o tempo
     acumulado em cada ponto. Tudo é calculado UMA vez, fora do loop de quadros.
     ========================================================================== */
  function buildStroke(raw) {
    const n = raw.x.length;
    const x = Float32Array.from(raw.x);
    const y = Float32Array.from(raw.y);

    // O extrator pode devolver o vetor de espessura mais curto que o de posição
    // (o traço g3s1 vem com 838 espessuras para 840 pontos). Sem isso, os
    // últimos segmentos recebem lineWidth = NaN — que o Canvas ignora em
    // silêncio, mantendo a espessura anterior. Repetimos o último valor válido.
    const w = new Float32Array(n);
    const wSrc = raw.w || [];
    let lastW = wSrc.length ? wSrc[0] : 1;
    for (let i = 0; i < n; i++) {
      const v = wSrc[i];
      if (typeof v === 'number' && isFinite(v)) lastW = v;
      w[i] = lastW;
    }
    const ds = new Float32Array(n);   // comprimento do segmento que chega em i
    const s = new Float32Array(n);    // comprimento de arco acumulado

    for (let i = 1; i < n; i++) {
      ds[i] = Math.hypot(x[i] - x[i - 1], y[i] - y[i - 1]);
      s[i] = s[i - 1] + ds[i];
    }
    const length = s[n - 1];

    // --- raio de curvatura local (curvatura de Menger sobre uma janela) ------
    const h = Math.min(CONFIG.curvWindow, Math.max(1, (n - 1) >> 1));
    const R = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      const a = Math.max(0, i - h), c = Math.min(n - 1, i + h);
      const abx = x[i] - x[a], aby = y[i] - y[a];
      const bcx = x[c] - x[i], bcy = y[c] - y[i];
      const acx = x[c] - x[a], acy = y[c] - y[a];
      const cross = Math.abs(abx * bcy - aby * bcx);
      const la = Math.hypot(abx, aby), lb = Math.hypot(bcx, bcy), lc = Math.hypot(acx, acy);
      R[i] = cross < 1e-6 ? CONFIG.maxRadius : (la * lb * lc) / (2 * cross);
    }

    // --- velocidade: lei da potência 2/3 ------------------------------------
    const v = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      v[i] = Math.pow(clamp(R[i], CONFIG.minRadius, CONFIG.maxRadius), CONFIG.speedExponent);
    }
    // suaviza o perfil para que a mão não "tremelique" entre amostras vizinhas
    const vs = new Float32Array(n);
    const k = CONFIG.speedSmooth >> 1;
    for (let i = 0; i < n; i++) {
      let acc = 0, cnt = 0;
      for (let j = i - k; j <= i + k; j++) { acc += v[clamp(j, 0, n - 1)]; cnt++; }
      vs[i] = acc / cnt;
    }
    // --- rampas de partida e de chegada -------------------------------------
    for (let i = 0; i < n; i++) {
      const inR = clamp(s[i] / CONFIG.entryRamp, 0, 1);
      const outR = clamp((length - s[i]) / CONFIG.exitRamp, 0, 1);
      const ramp = CONFIG.rampFloor + (1 - CONFIG.rampFloor) * Math.pow(Math.min(inR, outR), 0.6);
      vs[i] *= ramp;
    }

    // --- tempo natural acumulado em cada ponto -------------------------------
    const t = new Float32Array(n);
    for (let i = 1; i < n; i++) {
      const vAvg = 0.5 * (vs[i - 1] + vs[i]);
      t[i] = t[i - 1] + ds[i] / Math.max(vAvg, 1e-4);
    }

    return { g: raw.g, s: raw.s, src: raw.src, n, x, y, w, ds, t, length, natural: t[n - 1] };
  }

  /* ============================================================================
     O PREPARO NÃO ACONTECE MAIS NO CARREGAMENTO DO SCRIPT.

     `buildStroke` roda sobre 2604 pontos e, para cada um, mede curvatura numa
     janela, tira raiz cúbica, aplica média móvel e integra o tempo. Isso
     acontecia no instante em que o arquivo era avaliado — ou seja, dentro do
     caminho crítico, junto com tudo o mais que a página precisa fazer para
     aparecer.

     O TAMANHO DISSO, MEDIDO E NÃO CHUTADO: 0,8ms de mediana num desktop
     (5,3ms na primeira execução, antes do JIT aquecer). Não é o vilão da
     página — cheguei a suspeitar que fosse, medi, e não era. Num celular
     intermediário, 4 a 8 vezes mais lento, isso vira algo entre 3 e 25ms.

     Ainda assim vale mover, e a razão é o MOMENTO, não o tamanho: a
     assinatura só começa a ser escrita depois que a cortina do preloader
     sobe, quase dois segundos mais tarde. Trabalho que ninguém está
     esperando não tem por que disputar o instante mais concorrido da vida da
     página, ainda mais quando existe um segundo inteiro de ociosidade logo em
     seguida.

     (Também testei trocar o literal de dados por JSON.parse, que costuma ser
     mais rápido de analisar. Aqui não é: 0,2ms contra menos de 0,1ms do
     literal. Ficou como está.)

     Agora ela roda em tempo ocioso (`requestIdleCallback`), entre o
     carregamento e a subida da cortina. As funções que dependem do resultado
     chamam `prepararTracos()` antes de usar — a função é idempotente, então se
     por qualquer motivo o tempo ocioso não tiver chegado, o preparo acontece
     ali na hora e nada deixa de funcionar.
     ========================================================================== */
  let strokes = null;
  let TOTAL = 0;

  function prepararTracos() {
    if (strokes) return;                       // já está pronto

    strokes = DATA.strokes.map(buildStroke);

    /* --- linha do tempo: normaliza para a duração total e insere as pausas -- */
    let pauses = CONFIG.leadIn;
    for (let i = 1; i < strokes.length; i++) {
      pauses += strokes[i].g === strokes[i - 1].g ? CONFIG.liftInGroup : CONFIG.liftBetweenGroups;
    }
    const drawBudget = CONFIG.totalDuration - pauses - CONFIG.tailHold;
    const naturalTotal = strokes.reduce((a, st) => a + st.natural, 0);
    const scale = drawBudget / naturalTotal;   // um único fator: preserva o ritmo relativo

    let cursorTime = CONFIG.leadIn;
    strokes.forEach((st, i) => {
      if (i > 0) cursorTime += st.g === strokes[i - 1].g ? CONFIG.liftInGroup : CONFIG.liftBetweenGroups;
      st.t0 = cursorTime;
      for (let j = 0; j < st.n; j++) st.t[j] *= scale;
      st.duration = st.t[st.n - 1];
      st.t1 = st.t0 + st.duration;
      cursorTime = st.t1;
    });
    TOTAL = cursorTime + CONFIG.tailHold;
  }

  /* Tempo ocioso, com teto: o `timeout` garante que o preparo não fique
     esperando uma folga que nunca chega. 1200ms ainda cabe folgado antes da
     cortina subir (2,2s no pior caso). Sem requestIdleCallback, um timeout
     curto já tira o trabalho do caminho crítico. */
  if ('requestIdleCallback' in window) {
    requestIdleCallback(prepararTracos, { timeout: 1200 });
  } else {
    setTimeout(prepararTracos, 200);
  }

  /* ============================================================================
     2. ENQUADRAMENTO RESPONSIVO
     ========================================================================== */
  const view = { scale: 1, dx: 0, dy: 0, dpr: 1, w: 0, h: 0 };

  // a caixa do canvas só existe depois que o flex da hero resolve a altura;
  // desenhar antes disso é o que fazia a assinatura "não aparecer"
  function boxOf(el) {
    const cs = getComputedStyle(el);
    const rect = el.getBoundingClientRect();
    const padX = (parseFloat(cs.paddingLeft) || 0) + (parseFloat(cs.paddingRight) || 0);
    const padY = (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0);
    return { w: rect.width - padX, h: rect.height - padY };
  }

  function stageReady() {
    const b = boxOf(stage);
    return b.w > 16 && b.h > 16;
  }

  function layout() {
    loteAberto = false;                        // o transform vai mudar debaixo dele
    const b = boxOf(stage);
    const cw = Math.max(1, b.w);
    const ch = Math.max(1, b.h);
    const dpr = Math.min(window.devicePixelRatio || 1, 3);
    const [bx, by, bw, bh] = DATA.bbox;

    /* O enquadramento vem do CSS (`--assinatura-fill` no .assinatura-wrap), e
       não mais de um número fixo aqui: ele muda com o tamanho da tela, que é
       uma decisão de layout e não de motor. O `CONFIG.fillRatio` continua
       valendo como piso, para o caso de a variável não existir. */
    const declarado = parseFloat(
      getComputedStyle(stage).getPropertyValue('--assinatura-fill'));
    const preencher = declarado > 0 ? declarado : CONFIG.fillRatio;

    const sc = Math.min(cw / bw, ch / bh) * preencher;

    view.dpr = dpr; view.scale = sc; view.w = cw; view.h = ch;
    view.dx = (cw - bw * sc) / 2 - bx * sc;
    view.dy = (ch - bh * sc) / 2 - by * sc;

    canvas.style.width = cw + 'px';
    canvas.style.height = ch + 'px';
    canvas.width = Math.round(cw * dpr);
    canvas.height = Math.round(ch * dpr);

    ctx.setTransform(dpr * sc, 0, 0, dpr * sc, dpr * view.dx, dpr * view.dy);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = COLOR;
    ctx.fillStyle = COLOR;
  }

  // limpa mantendo o canvas transparente (o fundo escuro da página aparece)
  function clearPaper() {
    loteAberto = false;                        // o que estivesse aberto some junto
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.restore();
    ctx.fillStyle = COLOR;
  }

  /* ============================================================================
     3. DEPÓSITO DE TINTA
     O estado guarda exatamente onde a ponta parou. Cada quadro desenha só o
     trecho novo, do ponto anterior até a posição atual da ponta.
     ========================================================================== */
  const pen = { si: 0, i: 0, f: 0, down: false, x: 0, y: 0 };

  function resetPen() {
    pen.si = 0; pen.i = 0; pen.f = 0; pen.down = false;
    loteAberto = false; loteW = -1;
  }

  function penDown(st) {
    fecharLote();                              // a gota não pode entrar no lote
    pen.x = st.x[0]; pen.y = st.y[0];
    pen.i = 0; pen.f = 0; pen.down = true;
    // a caneta encosta: primeira gota de tinta, do tamanho do traço naquele ponto
    ctx.beginPath();
    ctx.arc(pen.x, pen.y, st.w[0] / 2, 0, Math.PI * 2);
    ctx.fill();
  }

  // desenha do ponto atual da ponta até (idx + frac) do movimento `st`
  function inkTo(st, idx, frac) {
    while (pen.i < idx) {
      const j = pen.i + 1;
      segment(pen.x, pen.y, st.x[j], st.y[j], lerpW(st, pen.i, pen.f), st.w[j]);
      pen.x = st.x[j]; pen.y = st.y[j]; pen.i = j; pen.f = 0;
    }
    if (frac > pen.f || (idx === pen.i && frac > 0)) {
      const j = Math.min(pen.i + 1, st.n - 1);
      const nx = st.x[pen.i] + (st.x[j] - st.x[pen.i]) * frac;
      const ny = st.y[pen.i] + (st.y[j] - st.y[pen.i]) * frac;
      if (nx !== pen.x || ny !== pen.y) {
        segment(pen.x, pen.y, nx, ny, lerpW(st, pen.i, pen.f), lerpW(st, pen.i, frac));
        pen.x = nx; pen.y = ny;
      }
      pen.f = frac;
    }
  }

  function lerpW(st, i, f) {
    const j = Math.min(i + 1, st.n - 1);
    return st.w[i] + (st.w[j] - st.w[i]) * f;
  }

  /* ==========================================================================
     UM TRAÇO POR LOTE, E NÃO UM POR SEGMENTO

     São 2.604 pontos escritos em 2,4s: 18 segmentos por quadro a 60Hz. Cada um
     era um `beginPath` + `moveTo` + `lineTo` + `stroke` — dezoito chamadas de
     desenho por quadro, cada uma com as suas duas pontas arredondadas para o
     antialiasing resolver. Num iPhone, com o canvas em 3x, é aí que a escrita
     ganha aquele andar aos soluços: não é a conta que custa, é o número de
     chamadas.

     Segmentos vizinhos quase sempre têm a MESMA espessura — a caneta engrossa
     e afina devagar. Arredondando a espessura em degraus de 0,25 unidade de
     arte (menos de 2% do traço, invisível), os vizinhos passam a caber num
     `Path2D` só, com um `stroke` no fim. As dezoito chamadas viram três ou
     quatro.

     E o desenho fica RIGOROSAMENTE igual — melhor, até: onde antes duas pontas
     redondas se sobrepunham, agora há uma junta redonda de verdade
     (`lineJoin: round`). Como a cor é opaca, sobreposição e junta pintam o
     mesmo pixel.

     A regra do lote: ele continua enquanto a espessura for a mesma E o próximo
     segmento começar exatamente onde o anterior parou. Qualquer quebra fecha o
     lote e abre outro. `fecharLote` é chamado no fim de cada quadro e antes de
     qualquer outro desenho no contexto — uma gota de tinta, uma limpeza, uma
     troca de transform. Path aberto atravessando uma dessas seria tinta no
     lugar errado.
     ======================================================================== */
  let loteAberto = false, loteW = -1, loteX = 0, loteY = 0;

  function fecharLote() {
    if (!loteAberto) return;
    ctx.stroke();
    loteAberto = false;
  }

  function segment(x0, y0, x1, y1, w0, w1) {
    const w = Math.round((w0 + w1) * 2) / 4;   // degraus de 0,25

    if (!loteAberto || w !== loteW || x0 !== loteX || y0 !== loteY) {
      fecharLote();
      ctx.lineWidth = w;
      ctx.beginPath();
      ctx.moveTo(x0, y0);
      loteW = w;
      loteAberto = true;
    }

    ctx.lineTo(x1, y1);
    loteX = x1;
    loteY = y1;
  }

  // localiza (índice, fração) correspondente a um tempo local dentro do traço
  function locate(st, time) {
    if (time >= st.duration) return [st.n - 1, 0];
    let lo = 0, hi = st.n - 1;
    while (lo + 1 < hi) {
      const mid = (lo + hi) >> 1;
      if (st.t[mid] <= time) lo = mid; else hi = mid;
    }
    const span = st.t[lo + 1] - st.t[lo];
    return [lo, span > 0 ? (time - st.t[lo]) / span : 0];
  }

  /* ============================================================================
     4. LOOP DE ANIMAÇÃO
     ========================================================================== */
  let startedAt = 0, playing = false, elapsed = 0, rafId = 0, everPlayed = false;

  function paintUpTo(time) {
    while (pen.si < strokes.length) {
      const st = strokes[pen.si];
      if (time < st.t0) break;                 // caneta ainda no ar
      if (!pen.down) penDown(st);
      const local = time - st.t0;
      if (local >= st.duration) {
        inkTo(st, st.n - 1, 0);                // fecha o movimento por inteiro
        pen.si++; pen.down = false; pen.i = 0; pen.f = 0;
        continue;                              // o próximo já pode ter começado
      }
      const [i, f] = locate(st, local);
      inkTo(st, i, f);
      break;
    }
    fecharLote();      // fecha o que sobrou do quadro
  }

  function frame(now) {
    if (!playing) return;
    elapsed = now - startedAt;
    paintUpTo(Math.min(elapsed, TOTAL));
    if (elapsed >= TOTAL) { playing = false; rafId = 0; return; }
    rafId = requestAnimationFrame(frame);
  }

  function play() {
    if (!stageReady()) return;                 // sem caixa ainda: não desenha
    prepararTracos();                          // idempotente: normalmente já rodou no ocioso
    cancelAnimationFrame(rafId);
    layout();
    clearPaper();
    resetPen();
    elapsed = 0;
    playing = true;
    everPlayed = true;
    startedAt = performance.now();
    rafId = requestAnimationFrame(frame);
  }

  function renderComplete() {
    if (!stageReady()) return;
    prepararTracos();
    layout();
    clearPaper();
    resetPen();
    paintUpTo(TOTAL);
    elapsed = TOTAL;
    everPlayed = true;
    playing = false;
  }

  /* --- redimensionar: redesenha o estado atual na nova escala --------------- */
  let resizeTimer = 0;
  function onResize() {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      if (!stageReady()) return;
      if (!everPlayed && !playing) return;     // nada escrito ainda: nada a refazer
      prepararTracos();
      const t = playing ? elapsed : (everPlayed ? TOTAL : 0);
      layout();
      clearPaper();
      resetPen();
      paintUpTo(Math.min(t, TOTAL));           // reconstrói só o que já foi escrito
      if (playing) startedAt = performance.now() - elapsed;
    }, 80);
  }

  window.addEventListener('resize', onResize);
  window.addEventListener('orientationchange', onResize);

  // o flex da hero pode resolver a altura depois do load (fontes, imagens...)
  if ('ResizeObserver' in window) {
    new ResizeObserver(onResize).observe(stage);
  }

  /* --- início: espera a caixa existir e escreve, uma vez só ---------------- */
  const reduced = window.matchMedia &&
                  window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function whenReady(fn) {
    if (stageReady()) { fn(); return; }
    let tries = 0;
    const timer = setInterval(() => {
      if (stageReady()) { clearInterval(timer); fn(); }
      else if (++tries > 80) { clearInterval(timer); console.warn('assinatura: canvas sem tamanho.'); }
    }, 50);
  }

  function start() {
    if (reduced) { renderComplete(); return; }  // acessibilidade: já mostra pronta

    /* Se existe preloader na página, quem manda tocar é ele (js/efeitos.js,
       logo depois que a cortina sobe). Sem esta guarda a assinatura seria
       escrita inteira ATRÁS do preloader — o observer abaixo enxerga o canvas
       normalmente, porque a cortina só cobre visualmente, não tira o canvas
       da tela — e a pessoa só veria o resultado já pronto. */
    if (document.getElementById('preloader')) return;

    if (!('IntersectionObserver' in window)) { play(); return; }

    // escreve na primeira vez que o canvas aparece e desliga o observer:
    // uma única execução por carregamento de página
    const io = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        io.disconnect();
        play();
        break;
      }
    }, { threshold: 0.25 });

    io.observe(canvas);
  }

  const boot = () => whenReady(start);

  if (document.readyState === 'complete') boot();
  else window.addEventListener('load', boot);

  // exposto apenas para inspeção/testes no console
  window.__assinatura = {
    play, renderComplete, config: CONFIG, prepararTracos,
    /* getters, e não valores: os traços só existem depois do preparo, então
       capturá-los aqui na criação do objeto entregaria `null` para sempre */
    get strokes(){ return strokes; },
    get TOTAL(){ return TOTAL; }
  };
})();